class ValueStoreConstructorFormatTest {

	@TempDir
	Path directory;

	@ParameterizedTest
	@CsvSource({ "false,false", "false,true", "true,false", "true,true" })
	void bareFreshDictionaryUsesTheCompleteCurrentWriterFormat(boolean inline, boolean ordered) throws Exception {
		LmdbStoreConfig config = config(inline, ordered);
		ValueStore values = new ValueStore(directory.resolve("values").toFile(), config);
		try {
			assertFormat(values.getFormat(), LmdbStoreFormat.forNewStore(config));
			ValueStore.FreshValueSession session = values.startFreshValueSessionIfEmpty();
			assertThat(session).as("format bootstrap must not create ordinary dictionary owners").isNotNull();
			values.discardFreshValueSession(session);
		} finally {
			values.close();
		}
	}

	@ParameterizedTest
	@CsvSource({ "false,false", "false,true", "true,false", "true,true" })
	void bareColdReopenPreservesActualCurrentEncodingAndStableOwners(boolean inline, boolean ordered) throws Exception {
		LmdbStoreConfig config = config(inline, ordered).setTripleIndexes("spoc,posc");
		Path valuesDirectory = directory.resolve("values");
		StoreProperties properties = new StoreProperties(valuesDirectory.toFile());
		LmdbStoreFormat format = LmdbStoreFormat.forNewStore(config);
		format.initializeProperties(properties);
		// This fixture owns durable standalone publication; the explicit codec constructor does not publish its fence.
		Files.createDirectories(valuesDirectory);
		LmdbStore.writeCoreLiteralReferenceMarker(valuesDirectory);
		properties.save();
		var vf = SimpleValueFactory.getInstance();
		Value[] terms = {
				vf.createLiteral(42),
				vf.createLiteral("2026-10-20T12:34:56.000Z", XSD.DATETIME),
				vf.createLiteral("original mixed-case owner", "eN"),
				vf.createLiteral("dictionary text " + "x".repeat(300), XSD.STRING)
		};
		long[] ids = new long[terms.length];
		String[] labels = new String[terms.length];
		String[] languages = new String[terms.length];
		ValueStore initial = new ValueStore(valuesDirectory.toFile(), properties, config, false, null, format, false);
		try {
			initial.startTransaction(true);
			for (int i = 0; i < terms.length; i++) {
				ids[i] = initial.storeValue(terms[i]);
			}
			initial.commit();
			initial.clearCaches();
			for (int i = 0; i < terms.length; i++) {
				Literal stored = (Literal) initial.getValue(ids[i]);
				assertThat(stored).isEqualTo(terms[i]);
				labels[i] = stored.getLabel();
				languages[i] = stored.getLanguage().orElse(null);
			}
		} finally {
			initial.close();
		}
		// ValueStore initializes the term-index manifest and its sidecar; persist those owned settings before cold
		// reopen.
		assertThat(properties.getTripleIndexes()).as("standalone publication owns no statement index layout").isNull();
		properties.save();
		ValueStore reopened = new ValueStore(valuesDirectory.toFile(), config);
		try {
			for (int i = 0; i < terms.length; i++) {
				assertThat(reopened.getId(terms[i], false)).as("cold ID for term %s", i).isEqualTo(ids[i]);
				Literal stored = (Literal) reopened.getValue(ids[i]);
				assertThat(stored).isEqualTo(terms[i]);
				assertThat(stored.getLabel()).isEqualTo(labels[i]);
				assertThat(stored.getLanguage().orElse(null)).isEqualTo(languages[i]);
			}
			assertFormat(reopened.getFormat(), format);
		} finally {
			reopened.close();
		}
	}

	@Test
	void explicitCurrentCodecDoesNotPublishDurableOwnerMetadata() throws Exception {
		LmdbStoreConfig config = config(false, true);
		Path valuesDirectory = directory.resolve("values");
		StoreProperties properties = new StoreProperties(valuesDirectory.toFile());
		LmdbStoreFormat format = LmdbStoreFormat.forNewStore(config);
		format.initializeProperties(properties);
		ValueStore values = new ValueStore(valuesDirectory.toFile(), properties, config, false, null, format, false);
		try {
			assertFormat(values.getFormat(), format);
			values.startTransaction(true);
			values.storeValue(SimpleValueFactory.getInstance().createLiteral("explicit codec owner"));
			values.commit();
		} finally {
			values.close();
		}
		assertThat(valuesDirectory.resolve(StoreProperties.FILE_NAME)).doesNotExist();
		assertThat(valuesDirectory.resolve(LmdbStore.CORE_LITERAL_REFERENCE_MARKER_FILE)).doesNotExist();
		// Publishing only capabilities is incomplete ownership, even when an explicit codec wrote valid native bytes.
		properties.save();
		byte[] dataBefore = Files.readAllBytes(valuesDirectory.resolve("data.mdb"));
		byte[] propertiesBefore = Files.readAllBytes(valuesDirectory.resolve(StoreProperties.FILE_NAME));
		assertThatThrownBy(() -> {
			ValueStore rejected = new ValueStore(valuesDirectory.toFile(), config);
			rejected.close();
		}).isInstanceOf(SailException.class)
				.hasMessage("Writer capabilities and LmdbStore compatibility marker do not agree");
		assertThat(Files.readAllBytes(valuesDirectory.resolve("data.mdb"))).isEqualTo(dataBefore);
		assertThat(Files.readAllBytes(valuesDirectory.resolve(StoreProperties.FILE_NAME))).isEqualTo(propertiesBefore);
		assertThat(valuesDirectory.resolve(LmdbStore.CORE_LITERAL_REFERENCE_MARKER_FILE)).doesNotExist();
	}

	private static LmdbStoreConfig config(boolean inline, boolean ordered) {
		return new LmdbStoreConfig().setInlineLiterals(inline).setOrderedNumericIds(ordered);
	}

	private static void assertFormat(LmdbStoreFormat actual, LmdbStoreFormat expected) {
		assertThat(actual.getVersion()).isEqualTo(expected.getVersion());
		assertThat(actual.inlinesLiterals()).isEqualTo(expected.inlinesLiterals());
		assertThat(actual.usesOrderedNumericIds()).isEqualTo(expected.usesOrderedNumericIds());
		assertThat(actual.usesCoreDatatypeLiteralReferences()).isEqualTo(expected.usesCoreDatatypeLiteralReferences());
		assertThat(actual.usesCanonicalLanguageTags()).isEqualTo(expected.usesCanonicalLanguageTags());
		assertThat(actual.usesZeroFractionDateTimeIds()).isEqualTo(expected.usesZeroFractionDateTimeIds());
	}
}
